 function average(section,metric,semester,entity){const rs=selectedYears().map(y=>get(section,metric,y,semester,entity)),valid=rs.filter(numeric);return {section,metric,semester,course:section==='cursos'?entity:null,department:section!=='cursos'?entity:null,year:range(),value:valid.length?valid.reduce((s,r)=>s+r.value,0)/valid.length:null,status:valid.length?(valid.some(r=>r.status==='approximate')?'approximate':'derived'):rs.some(r=>r.status==='NC')?'NC':'ND',unit:valid[0]?.unit,n:valid.length,expected_n:rs.length,records:rs,derived_kind:'mean',semantic_note:state.tab==='department'&&section==='departamento_jupiter'&&creditMetricIds.includes(metric)?'Média apenas dos anos com a mesma cobertura comprovada nos quatro departamentos, para este indicador e período. Recortes NC ficam fora do cálculo; os valores adicionais já obtidos estão preservados em Dados complementares.':'Média aritmética dos anos documentados, para este mesmo indicador e semestre. Anos sem informação não entram como zero.'};}
 function coverage(section,metric,semester,entities){const ys=selectedYears(),cs=entities.map(c=>({c,years:ys.filter(y=>numeric(get(section,metric,y,semester,c.id)))}));const unequal=new Set(cs.map(c=>c.years.join(','))).size>1;return `<div class="coverage-strip"><span>Cobertura · ${esc(semLabel(semester))}</span>${cs.map(c=>`<span><strong>${esc(c.c.id)}</strong> ${c.years.length}/${ys.length} anos</span>`).join('')}</div>${unequal?'<div class="callout warning"><strong>As médias usam coberturas diferentes.</strong> Compare um intervalo com a mesma cobertura entre as séries selecionadas.</div>':''}`;}
